1	import { readFileSync } from "node:fs";
2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	export const main = (): void => {
5	  const input = readFileSync(0, "utf8");
6	  const scenario = JSON.parse(input) as Scenario;
7	  process.stdout.write(JSON.stringify(runScenario(scenario)));
8	};
9	
10	main();
11

1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Damage = {
8	  itemType: string;
9	  amount: number;
10	};
11	
12	export type Incident = {
13	  cause: string;
14	  damages: Damage[];
15	};
16	
17	export type Step = {
18	  op: string;
19	  items?: Item[];
20	  policy?: number;
21	  incident?: Incident;
22	};
23	
24	export type Customer = {
25	  yearsWithMHPCO: number;
26	};
27	
28	export type Scenario = {
29	  customer: Customer;
30	  steps: Step[];
31	};
32	
33	export type QuoteResult = {
34	  premium: number;
35	};
36	
37	export type ClaimResult = {
38	  payout: number;
39	  remainingCap: number;
40	};
41	
42	export type Result = QuoteResult | ClaimResult;
43	
44	export type ScenarioOutcome = {
45	  results: Result[];
46	};
47	
48	const PROCESSING_FEE = 5;
49	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
50	  sword: 100,
51	  amulet: 60,
52	  staff: 80,
53	  potion: 40,
54	  rune: 25,
55	  moonstone: 25,
56	};
57	
58	// Percentages are applied as the exact fraction `amount * percent / 100`
59	// rather than via a float factor such as `amount * 0.1`, which drifts.
60	const percentOf = (percent: number, amount: number): number =>
61	  (amount * percent) / 100;
62	
63	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
64	const CURSE_SURCHARGE_PERCENT = 50;
65	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
66	const HIGH_ENCHANTMENT_THRESHOLD = 5;
67	
68	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
69	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
70	
71	const LOYALTY_DISCOUNT_PERCENT = 20;
72	const LOYALTY_YEARS_THRESHOLD = 2;
73	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
74	
75	// Discounts attached to the policy are percentages of the policy base premium,
76	// so they can be summed as percentages and applied in one go.
77	const policyDiscountsOn = (
78	  policyBasePremium: number,
79	  customer: Customer,
80	  contractsAlreadyIssued: number,
81	): number => {
82	  const loyaltyPercent =
83	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
84	      ? LOYALTY_DISCOUNT_PERCENT
85	      : 0;
86	  const followUpPercent =
87	    contractsAlreadyIssued > 0 ? FOLLOW_UP_DISCOUNT_PERCENT : 0;
88	  return percentOf(loyaltyPercent + followUpPercent, policyBasePremium);
89	};
90	
91	// Surcharges attached to a single item are a percentage of that item's own
92	// base premium from the price list (never of the policy base premium).
93	const surchargeForItem = (item: Item): number => {
94	  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
95	  const highEnchantmentPercent =
96	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
97	      ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT
98	      : 0;
99	  return percentOf(
100	    cursePercent + highEnchantmentPercent,
101	    BASE_PREMIUM_BY_TYPE[item.type],
102	  );
103	};
104	
105	const itemSurchargesOf = (items: Item[]): number =>
106	  items.reduce((total, item) => total + surchargeForItem(item), 0);
107	
108	const BLOCK_SIZE = 3;
109	const BLOCK_BASE_PREMIUM = 60;
110	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
111	
112	const countByType = (items: Item[]): Map<string, number> => {
113	  const counts = new Map<string, number>();
114	  for (const item of items) {
115	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
116	  }
117	  return counts;
118	};
119	
120	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
121	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
122	// items never form a block.
123	const basePremiumForAlikeItems = (type: string, count: number): number =>
124	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
125	    ? BLOCK_BASE_PREMIUM
126	    : count * BASE_PREMIUM_BY_TYPE[type];
127	
128	// An item type that is not on the price list has neither a premium nor an
129	// insurance value, so neither a quote nor a claim can name one; rejecting it
130	// keeps a typo from silently becoming a NaN amount.
131	const rejectUnknownItemType = (type: string): void => {
132	  if (!(type in BASE_PREMIUM_BY_TYPE)) {
133	    throw new Error(`unknown item type: ${type}`);
134	  }
135	};
136	
137	const rejectUnknownItemTypes = (items: Item[]): void => {
138	  for (const item of items) {
139	    rejectUnknownItemType(item.type);
140	  }
141	};
142	
143	const policyBasePremiumOf = (items: Item[]): number =>
144	  [...countByType(items)].reduce(
145	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
146	    0,
147	  );
148	
149	// The processing fee is added after every percentage modifier, so it is never
150	// itself discounted. Only the final premium is rounded, and always up.
151	const premiumFor = (
152	  items: Item[],
153	  customer: Customer,
154	  contractsAlreadyIssued: number,
155	): number => {
156	  rejectUnknownItemTypes(items);
157	  const policyBasePremium = policyBasePremiumOf(items);
158	  const surcharges =
159	    itemSurchargesOf(items) + firstInsuranceSurchargeOn(policyBasePremium);
160	  const discounts = policyDiscountsOn(
161	    policyBasePremium,
162	    customer,
163	    contractsAlreadyIssued,
164	  );
165	  return Math.ceil(
166	    policyBasePremium + surcharges - discounts + PROCESSING_FEE,
167	  );
168	};
169	
170	const DEDUCTIBLE = 100;
171	const CAP_MULTIPLIER = 2;
172	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
173	  sword: 1000,
174	  amulet: 600,
175	  staff: 800,
176	  potion: 400,
177	  rune: 250,
178	  moonstone: 250,
179	};
180	
181	// The cap is twice the insurance sum of the policy's items, taken from the
182	// unmodified insurance values in the price list.
183	const insuranceSumOf = (items: Item[]): number =>
184	  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);
185	
186	const HALF_REIMBURSEMENT_PERCENT = 50;
187	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
188	
189	// The reimbursement rate of a damage depends on the damaged item itself, so
190	// the damage entry is matched against the insured items of its policy.
191	const reimbursableAmountFor = (damage: Damage, item: Item): number =>
192	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
193	    ? percentOf(HALF_REIMBURSEMENT_PERCENT, damage.amount)
194	    : damage.amount;
195	
196	// A damage can only be settled against an item the policy actually insures.
197	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
198	  const item = insuredItems.find(({ type }) => type === damage.itemType);
199	  if (item === undefined) {
200	    throw new Error(`item type not covered by the policy: ${damage.itemType}`);
201	  }
202	  return item;
203	};
204	
205	const payoutForDamage = (damage: Damage, insuredItems: Item[]): number =>
206	  reimbursableAmountFor(damage, insuredItemFor(damage, insuredItems)) -
207	  DEDUCTIBLE;
208	
209	// A damage entry stands for one damaged item, so a policy insuring one sword
210	// cannot back two sword damages.
211	const rejectMoreDamagesThanInsuredItems = (
212	  damages: Damage[],
213	  insuredItems: Item[],
214	): void => {
215	  const insuredCounts = countByType(insuredItems);
216	  const damageCounts = countByType(
217	    damages.map(({ itemType }) => ({ type: itemType })),
218	  );
219	  for (const [type, count] of damageCounts) {
220	    if (count > (insuredCounts.get(type) ?? 0)) {
221	      throw new Error(
222	        `more damage entries than insured items for item type: ${type}`,
223	      );
224	    }
225	  }
226	};
227	
228	// A single unsettleable damage rejects the whole claim, so every damage is
229	// checked before any of them is paid out. The checks are listed in the order
230	// they are reported: the most specific complaint about a damage entry wins.
231	const rejectUnsettleableDamages = (
232	  damages: Damage[],
233	  insuredItems: Item[],
234	): void => {
235	  for (const damage of damages) {
236	    if (damage.amount < 0) {
237	      throw new Error(`negative damage amount: ${damage.amount}`);
238	    }
239	    rejectUnknownItemType(damage.itemType);
240	    insuredItemFor(damage, insuredItems); // throws if the policy does not cover it
241	  }
242	  rejectMoreDamagesThanInsuredItems(damages, insuredItems);
243	};
244	
245	// The cap belongs to the policy, not to the single claim, so successive claims
246	// on the same policy share it and each payout is clamped to what is left.
247	const claimResultFor = (
248	  damages: Damage[],
249	  insuredItems: Item[],
250	  capAlreadyConsumed: number,
251	): ClaimResult => {
252	  rejectUnsettleableDamages(damages, insuredItems);
253	  const remainingCapBefore =
254	    CAP_MULTIPLIER * insuranceSumOf(insuredItems) - capAlreadyConsumed;
255	  const reimbursable = damages.reduce(
256	    (total, damage) => total + payoutForDamage(damage, insuredItems),
257	    0,
258	  );
259	  const payout = Math.floor(Math.min(reimbursable, remainingCapBefore));
260	  return { payout, remainingCap: remainingCapBefore - payout };
261	};
262	
263	// Only a quote issues a contract; a claim step is not a contract and must not
264	// advance the count the follow-up discount is based on.
265	const issuesContract = (step: Step): boolean => step.op !== "claim";
266	
267	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
268	  const capConsumedByPolicy = new Map<number, number>();
269	  let contractsAlreadyIssued = 0;
270	  const results = scenario.steps.map((step) => {
271	    if (issuesContract(step)) {
272	      const premium = premiumFor(
273	        step.items ?? [],
274	        scenario.customer,
275	        contractsAlreadyIssued,
276	      );
277	      contractsAlreadyIssued += 1;
278	      return { premium };
279	    }
280	    const policyIndex = step.policy ?? 0;
281	    const capAlreadyConsumed = capConsumedByPolicy.get(policyIndex) ?? 0;
282	    const result = claimResultFor(
283	      step.incident?.damages ?? [],
284	      scenario.steps[policyIndex].items ?? [],
285	      capAlreadyConsumed,
286	    );
287	    capConsumedByPolicy.set(policyIndex, capAlreadyConsumed + result.payout);
288	    return result;
289	  });
290	  return { results };
291	};
